import pandas as pd

LABELS = ['claude-fable-5', 'claude-opus-4-6', 'claude-opus-4-8', 'claude-opus-5', 'claude-sonnet-5', 'gemini-3.1-pro-preview', 'gemini-3.6-flash', 'gemini-3.7-flash', 'gemini-3.8-flash', 'glm-5.3', 'glm-5.3-flash', 'gpt-5.5', 'gpt-5.6-luna', 'gpt-5.6-sol', 'gpt-5.6-terra', 'gpt-6-astra', 'kimi-k3', 'qwen3.8-max']

# ---------------------------------------------------------------- ntllm/features/tfidf.py
"""TF-IDF features, fit on the train split only, with a prompt-frequency topic-word filter.

Leakage rule (DESIGN.md, Leakage Risks): the vocabulary and IDF see only train-split rows.
`fit` asserts every row it gets is from the train split, and `assert_disjoint` checks that
the rows being transformed share no prompt with the rows the vocabulary was fit on.

Topic-word filter (BUILD_BRIEF Chunk 3; ablation 4): every prompt has ~18 answers, all on
the same topic, so words tied to one prompt's topic look like strong features but carry no
model style. A term is kept only if it appears in at least `min_prompts` distinct train
prompts. Style words ("delve", "Certainly", "—") spread across prompts and survive; topic
words ("photosynthesis") appear under one or two prompts and are dropped. min_prompts=1
turns the filter off.
"""
import numpy as np
import pandas as pd
import scipy.sparse as sp
from sklearn.feature_extraction.text import TfidfVectorizer
from sklearn.preprocessing import normalize


def prompt_frequency(X: sp.spmatrix, prompt_ids) -> np.ndarray:
    """Number of distinct prompts each column (term) appears under."""
    codes, _ = pd.factorize(pd.Series(prompt_ids))
    P = sp.csr_matrix((np.ones(len(codes)), (codes, np.arange(len(codes)))))
    present = (P @ (X > 0).astype(np.float32)) > 0  # (n_prompts, n_terms)
    return np.asarray(present.sum(axis=0)).ravel()


class TfidfFeatures:
    """Word and/or char n-gram TF-IDF with the topic-word filter.

    analyzer: "word", "char" (char_wb n-grams) or "both" (side by side, each L2-normalized,
    then the whole row re-normalized).
    """

    def __init__(self, analyzer="word", word_ngram=(1, 2), char_ngram=(2, 5),
                 min_df=2, max_features=None, sublinear_tf=True, lowercase=False,
                 min_prompts=3):
        self.analyzer, self.min_prompts = analyzer, min_prompts
        common = dict(min_df=min_df, max_features=max_features, sublinear_tf=sublinear_tf,
                      lowercase=lowercase, dtype=np.float32)
        self.vecs = {}
        if analyzer in ("word", "both"):
            # Keep punctuation as tokens: em dashes, colons, bullets are style signal.
            self.vecs["word"] = TfidfVectorizer(analyzer="word", ngram_range=tuple(word_ngram),
                                                token_pattern=r"(?u)\b\w+\b|[^\w\s]", **common)
        if analyzer in ("char", "both"):
            self.vecs["char"] = TfidfVectorizer(analyzer="char_wb", ngram_range=tuple(char_ngram),
                                                **common)
        if not self.vecs:
            raise ValueError(f"analyzer must be word, char or both, got {analyzer!r}")

    def fit(self, df: pd.DataFrame) -> "TfidfFeatures":
        """df needs text, prompt_id, split. Only train-split rows are allowed."""
        splits = set(df["split"])
        assert splits == {"train"}, f"TF-IDF must be fit on the train split only, got {splits}"
        self.fit_ids_ = set(df["id"])
        self.fit_prompts_ = set(df["prompt_id"])
        self.keep_, self.stats_ = {}, {}
        for name, vec in self.vecs.items():
            X = vec.fit_transform(df["text"])
            pf = prompt_frequency(X, df["prompt_id"])
            keep = np.flatnonzero(pf >= self.min_prompts)
            self.keep_[name] = keep
            self.stats_[name] = {"vocab": X.shape[1], "kept": len(keep),
                                 "dropped_topic": X.shape[1] - len(keep)}
        return self

    def assert_disjoint(self, df: pd.DataFrame) -> None:
        """The rows being transformed must not share any row or prompt with the fit rows."""
        shared = self.fit_prompts_ & set(df["prompt_id"])
        assert not shared, f"transforming rows whose prompts the vocab was fit on: {sorted(shared)[:5]}"
        assert not (self.fit_ids_ & set(df["id"])), "transforming rows the vocab was fit on"

    def transform(self, texts) -> sp.csr_matrix:
        parts = [normalize(vec.transform(texts)[:, self.keep_[name]])
                 for name, vec in self.vecs.items()]
        X = parts[0] if len(parts) == 1 else normalize(sp.hstack(parts).tocsr())
        return X.tocsr()

    def fit_transform(self, df: pd.DataFrame) -> sp.csr_matrix:
        return self.fit(df).transform(df["text"])

    def feature_names(self) -> np.ndarray:
        return np.concatenate([np.char.add(f"{name}:", vec.get_feature_names_out()[self.keep_[name]].astype(str))
                               for name, vec in self.vecs.items()])

    def dropped_examples(self, n=15) -> dict:
        """A few dropped (topic) terms per analyzer, to eyeball that the filter hits topics."""
        out = {}
        for name, vec in self.vecs.items():
            names = vec.get_feature_names_out()
            dropped = np.setdiff1d(np.arange(len(names)), self.keep_[name])
            idf = vec.idf_[dropped]
            out[name] = names[dropped[np.argsort(idf)[:n]]].tolist()  # most common dropped terms
        return out

# ---------------------------------------------------------------- ntllm/models/linear.py
"""Naive Bayes and linear SVM on TF-IDF features (DESIGN.md, Models)."""
import numpy as np
from scipy.special import softmax
from sklearn.naive_bayes import ComplementNB, MultinomialNB
from sklearn.svm import LinearSVC



def make_model(name: str, *, alpha=0.1, C=1.0, nb_kind="complement", seed=0):
    if name == "nb":
        # ComplementNB is the usual fix for MultinomialNB's bias on text; both are offered.
        cls = ComplementNB if nb_kind == "complement" else MultinomialNB
        return cls(alpha=alpha)
    if name == "svm":
        return LinearSVC(C=C, random_state=seed, max_iter=5000)
    raise ValueError(f"model must be nb or svm, got {name!r}")


def scores(model, X) -> np.ndarray:
    """Per-class scores in LABELS order (blend features for Chunk 5).

    NB: log-probabilities. SVM: decision_function margins.
    """
    assert list(model.classes_) == LABELS, "model classes must be the 18 LABELS in order"
    if hasattr(model, "predict_log_proba"):
        return model.predict_log_proba(X)
    return model.decision_function(X)


def perplexity(model, X, y) -> float | None:
    """exp(mean negative log-likelihood of the true label). NB only: the SVM has no
    probabilities, and softmaxing margins would be a made-up number."""
    if not hasattr(model, "predict_log_proba"):
        return None
    lp = softmax(model.predict_log_proba(X), axis=1)  # renormalize (ComplementNB is loose)
    idx = np.searchsorted(LABELS, np.asarray(y))
    return float(np.exp(-np.mean(np.log(np.clip(lp[np.arange(len(idx)), idx], 1e-12, None)))))


# ---------------------------------------------------------------- config
MODE = 'timing'
FIT_ON = 'train'
C = 0.3
MIN_PROMPTS = 3
FEATURES = {'analyzer': 'both', 'word_ngram': [1, 2], 'char_ngram': [2, 5], 'min_df': 2, 'max_features': None, 'lowercase': False, 'min_prompts': 3}
DUMMY_ROWS = 4000
TRAIN_PROMPTS = ['p001', 'p006', 'p008', 'p009', 'p010', 'p011', 'p014', 'p015', 'p016', 'p017', 'p019', 'p021', 'p022', 'p023', 'p026', 'p029', 'p030', 'p031', 'p032', 'p034', 'p035', 'p036', 'p038', 'p039', 'p040', 'p041', 'p042', 'p043', 'p044', 'p047', 'p048', 'p049', 'p053', 'p055', 'p057', 'p058', 'p059', 'p060', 'p061', 'p062', 'p063', 'p064', 'p065', 'p067', 'p069', 'p071', 'p072', 'p074', 'p075', 'p076', 'p077', 'p080', 'p083', 'p084', 'p088', 'p092', 'p093', 'p095', 'p097', 'p098', 'p099', 'p100', 'p102', 'p104', 'p107', 'p108', 'p109', 'p110', 'p112', 'p113', 'p115', 'p117', 'p118', 'p119', 'p121', 'p127', 'p128', 'p132', 'p133', 'p136', 'p137', 'p138', 'p139', 'p140', 'p141', 'p142', 'p145', 'p147', 'p148', 'p149']


# ---------------------------------------------------------------- kernel main
import glob
import os
import time


INPUT = os.environ.get("NTLLM_INPUT", "/kaggle/input")
OUTPUT = os.environ.get("NTLLM_OUTPUT", "/kaggle/working")


def find(name):
    hits = sorted(glob.glob(os.path.join(INPUT, "**", name), recursive=True))
    assert hits, f"{name} not found under {INPUT}"
    return hits[0]


def main():
    t0 = time.time()
    full = pd.read_csv(find("train.csv"))
    train = full[full.prompt_id.isin(TRAIN_PROMPTS)] if FIT_ON == "train" else full
    assert FIT_ON == "all" or train.prompt_id.nunique() == len(TRAIN_PROMPTS)
    train = train.assign(split="train").reset_index(drop=True)

    if MODE == "timing":
        # Dummy test the size of the hidden one, drawn from passages outside the fit set.
        pool = full[~full.id.isin(train.id)] if FIT_ON == "train" else full
        test = pool.sample(n=DUMMY_ROWS, replace=True, random_state=0)[["text"]].reset_index(drop=True)
        test.insert(0, "id", [f"dummy{i:05d}" for i in range(len(test))])
    else:
        test = pd.read_csv(find("test.csv"))
    print(f"mode={MODE} fit_on={FIT_ON} C={C} min_prompts={MIN_PROMPTS} cpus={os.cpu_count()} "
          f"train={len(train)} test={len(test)}", flush=True)

    feats = TfidfFeatures(**FEATURES).fit(train)
    model = make_model("svm", C=C).fit(feats.transform(train.text), train.model)
    print(f"vocab: {feats.stats_}", flush=True)
    t1 = time.time()
    preds = model.predict(feats.transform(test.text))
    t2 = time.time()

    sub = pd.DataFrame({"id": test.id, "model": preds})
    assert sub.id.is_unique and set(sub.id) == set(test.id)
    assert set(sub.model) <= set(LABELS), set(sub.model) - set(LABELS)
    name = "submission.parquet" if MODE == "submit" else "timing_submission.parquet"
    os.makedirs(OUTPUT, exist_ok=True)
    sub.to_parquet(os.path.join(OUTPUT, name), index=False)

    per_row = (t2 - t1) / max(len(test), 1)
    print(f"fit {t1 - t0:.1f}s  predict {t2 - t1:.1f}s  ({per_row * 1000:.2f} ms/row)  "
          f"total {time.time() - t0:.1f}s", flush=True)
    print(f"projected for 4,000 rows: {per_row * 4000 / 60:.2f} min (limit 540 min)", flush=True)
    print(f"wrote {name}: {len(sub)} rows, {sub.model.nunique()} labels predicted", flush=True)


if __name__ == "__main__":
    main()
